import itertools
def sgn(p):
    return (-1)**sum(1 for i in range(len(p)) for j in range(i+1,len(p)) if p[i] > p[j])
for p in itertools.permutations(range(5)):
    inv = [0]*5
    for i,x in enumerate(p): inv[x] = i
    assert sgn(p) == sgn(tuple(inv))
    for k in range(5):
        for l in range(k+1,5):
            q = list(p); q[k], q[l] = q[l], q[k]
            assert sgn(tuple(q)) == -sgn(p)

import itertools
def inv(p, i, j): return p[i] > p[j]
n = 6
for p in itertools.permutations(range(n)):
    for k in range(n):
        for l in range(k+1, n):
            q = list(p); q[k], q[l] = q[l], q[k]
            assert inv(p,k,l) != inv(q,k,l)
            for m in range(k+1, l):
                assert (inv(p,k,m) != inv(q,k,m)) == (inv(p,m,l) != inv(q,m,l))
            for i in list(range(k)) + list(range(l+1, n)):
                a, b = (i, k) if i < k else (k, i)
                c, d = (i, l) if i < l else (l, i)
                assert inv(q,a,b) == inv(p,c,d) and inv(q,c,d) == inv(p,a,b)
            tot = sum(inv(p,i,j) for i in range(n) for j in range(i+1,n)) - sum(inv(q,i,j) for i in range(n) for j in range(i+1,n))
            assert tot % 2 == 1

