from sympy import Matrix, Rational, eye, ones, acos, pi
for n in range(1, 8):
    U = eye(n+1) - Rational(1, n+1)*ones(n+1, n+1)
    G = U.T*U
    for i in range(n+1):
        assert G[i,i] == Rational(n, n+1)
        for j in range(n+1):
            if i != j: assert G[i,j]/G[i,i] == Rational(-1, n)
assert acos(Rational(-1,2)) == 2*pi/3

from sympy import Matrix, sqrt
A = Matrix([[3,0],[4,5]])
assert A.T*A == Matrix([[25,20],[20,25]]) and (A.T*A).eigenvals() == {45:1, 5:1}
assert A*Matrix([1,1]) == Matrix([3,9]) and A*Matrix([1,-1]) == Matrix([3,-1]) and Matrix([3,9]).dot(Matrix([3,-1])) == 0
assert sqrt(45)*sqrt(5) == 15 == abs(A.det()) and sqrt(45) == 3*sqrt(5)
assert A.eigenvals() == {3:1, 5:1}

