from sympy import symbols, zeros, eye, binomial, expand, Matrix
l = symbols('l')
for k in range(1,6):
    N = zeros(k,k)
    for i in range(k-1): N[i,i+1] = 1
    assert N**k == zeros(k,k)
    for j in range(0,k+2):
        assert k - (N**j).rank() == min(j,k)
    J = l*eye(k) + N
    for m in range(0,9):
        S = zeros(k,k)
        for j in range(k): S += binomial(m,j)*l**(m-j)*N**j if m-j >= 0 else zeros(k,k)
        assert (J**m - S).applyfunc(expand) == zeros(k,k)
